'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array/uint32' );
var toWords = require( '@stdlib/number/uint64/base/to-words' ).assign;
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var assign = require( './assign.js' );


// VARIABLES //

var WORKSPACE = new Uint32Array( 4 );


// MAIN //

/**
* Performs bitwise shift to the right on a 64-bit unsigned integer.
*
* @param {Uint64} a - 64-bit unsigned integer
* @param {uinteger32} shift - number of bits to shift (0-63)
* @returns {Uint64} result
*
* @example
* var Uint64 = require( '@stdlib/number/uint64/ctor' );
*
* var a = new Uint64( 10 );
*
* var v = rightShift( a, 1 );
* // returns <Uint64>[ 5n ]
*/
function rightShift( a, shift ) {
	toWords( a, WORKSPACE, 1, 0 );
	assign( WORKSPACE[0], WORKSPACE[1], shift, WORKSPACE, 1, 2 );
	return Uint64.of( WORKSPACE[2], WORKSPACE[3] );
}


// EXPORTS //

module.exports = rightShift;
